import 'dart:convert';
import 'package:flutter/foundation.dart';
import 'package:matrix_ai_os/core/constants/app_constants.dart';
import 'package:matrix_ai_os/core/database/local_database_service.dart';

/// Categories of proactive insights generated by Matrix AI OS.
enum InsightType {
  spendingSpike('Spending Alert', 1),
  screenTimeNudge('Digital Wellbeing', 2),
  upcomingTicket('Upcoming Schedule', 3),
  systemOptimization('System Status', 4);

  final String label;
  final int priority;
  const InsightType(this.label, this.priority);
}

/// Represents an on-device contextual insight surfaced proactively to the user.
@immutable
class ProactiveInsight {
  final String id;
  final InsightType type;
  final String title;
  final String message;
  final DateTime timestamp;
  final Map<String, dynamic> metadata;

  const ProactiveInsight({
    required this.id,
    required this.type,
    required this.title,
    required this.message,
    required this.timestamp,
    this.metadata = const {},
  });

  @override
  String toString() => 'ProactiveInsight($type: $title - $message)';
}

/// Proactive On-Device Context Engine.
///
/// Continuously monitors local encrypted memories and daily aggregates
/// to deliver actionable, zero-leakage proactive suggestions.
class ProactiveContextEngine {
  final LocalDatabaseService _dbService;

  ProactiveContextEngine({required LocalDatabaseService dbService})
      : _dbService = dbService;

  /// Analyzes local encrypted nodes & daily summaries to generate active proactive insights.
  Future<List<ProactiveInsight>> generateProactiveInsights({
    DateTime? referenceDate,
  }) async {
    final insights = <ProactiveInsight>[];
    final now = referenceDate ?? DateTime.now();

    try {
      // 1. Spending Spike Evaluation
      final spendingInsight = await _evaluateSpendingSpike(now);
      if (spendingInsight != null) {
        insights.add(spendingInsight);
      }

      // 2. Screen Time Evaluation
      final screenTimeInsight = await _evaluateScreenTime(now);
      if (screenTimeInsight != null) {
        insights.add(screenTimeInsight);
      }

      // 3. Upcoming Document / Ticket Booking Evaluation
      final ticketInsight = await _evaluateUpcomingTickets(now);
      if (ticketInsight != null) {
        insights.add(ticketInsight);
      }
    } catch (e) {
      debugPrint('[ProactiveContextEngine] Error generating insights: $e');
    }

    // Sort by priority
    insights.sort((a, b) => a.type.priority.compareTo(b.type.priority));
    return insights;
  }

  /// Evaluates today's spend against the 7-day average from DailySummary records.
  Future<ProactiveInsight?> _evaluateSpendingSpike(DateTime now) async {
    final summaries = _dbService.getAllDailySummaries();
    if (summaries.isEmpty) return null;

    // Calculate 7-day historical daily average spend
    double totalPastSpend = 0.0;
    int daysCounted = 0;

    for (final s in summaries.take(7)) {
      if (s.totalSpent > 0) {
        totalPastSpend += s.totalSpent;
        daysCounted++;
      }
    }

    final avgDailySpend = daysCounted > 0 ? (totalPastSpend / daysCounted) : 0.0;

    // Calculate today's spending from recent transaction MemoryNodes
    final recentMemories = await _dbService.getRecentDecryptedNodes(limit: 40);
    double todaySpend = 0.0;

    for (final m in recentMemories) {
      if (m.category == MemoryCategory.transaction && _isSameDay(m.timestamp, now)) {
        if (m.metadataJson.isNotEmpty) {
          try {
            final data = jsonDecode(m.metadataJson) as Map<String, dynamic>;
            final txType = data['txType'] as String? ?? 'debit';
            if (txType == 'debit') {
              final amt = (data['amount'] as num?)?.toDouble() ?? 0.0;
              todaySpend += amt;
            }
          } catch (_) {}
        }
      }
    }

    // Trigger spending alert if today's spend exceeds 1.4x of 7-day daily average
    // or if today's spend > 2500 and average is under 1500
    if (avgDailySpend > 0 && todaySpend > (avgDailySpend * 1.4) && todaySpend > 100) {
      final percentOver = (((todaySpend - avgDailySpend) / avgDailySpend) * 100).toInt();
      return ProactiveInsight(
        id: 'spend_spike_${now.millisecondsSinceEpoch}',
        type: InsightType.spendingSpike,
        title: 'Spending Spike Detected',
        message:
            'You have spent \$${todaySpend.toStringAsFixed(2)} today, which is $percentOver% higher than your 7-day daily average (\$${avgDailySpend.toStringAsFixed(2)}).',
        timestamp: now,
        metadata: {
          'todaySpend': todaySpend,
          'avgDailySpend': avgDailySpend,
          'percentOver': percentOver,
        },
      );
    }

    return null;
  }

  /// Evaluates screen time for today (> 240 mins = 4 hours).
  Future<ProactiveInsight?> _evaluateScreenTime(DateTime now) async {
    final recentMemories = await _dbService.getRecentDecryptedNodes(limit: 30);

    int todayScreenTimeMins = 0;

    for (final m in recentMemories) {
      if (m.category == MemoryCategory.screenTime && _isSameDay(m.timestamp, now)) {
        if (m.metadataJson.isNotEmpty) {
          try {
            final data = jsonDecode(m.metadataJson) as Map<String, dynamic>;
            final mins = (data['totalUsageMinutes'] as num?)?.toInt() ?? 0;
            if (mins > todayScreenTimeMins) {
              todayScreenTimeMins = mins;
            }
          } catch (_) {}
        }
      }
    }

    if (todayScreenTimeMins >= 240) {
      final hours = (todayScreenTimeMins / 60).toStringAsFixed(1);
      return ProactiveInsight(
        id: 'screen_time_${now.millisecondsSinceEpoch}',
        type: InsightType.screenTimeNudge,
        title: 'Digital Wellbeing Nudge',
        message:
            'You have logged $hours hours ($todayScreenTimeMins mins) of active screen time today. Consider taking a digital detox break or stepping away for a walk.',
        timestamp: now,
        metadata: {'screenTimeMinutes': todayScreenTimeMins},
      );
    }

    return null;
  }

  /// Scans OCR documents for upcoming ticket bookings or travel within 48 hours.
  Future<ProactiveInsight?> _evaluateUpcomingTickets(DateTime now) async {
    final recentMemories = await _dbService.getRecentDecryptedNodes(limit: 50);

    for (final m in recentMemories) {
      if (m.category == MemoryCategory.ocrDoc && m.metadataJson.isNotEmpty) {
        try {
          final data = jsonDecode(m.metadataJson) as Map<String, dynamic>;
          final classification = data['classification'] as Map<String, dynamic>?;
          final docType = classification?['type'] as String? ?? '';

          if (docType.toLowerCase().contains('ticket') ||
              docType.toLowerCase().contains('booking')) {
            final entities = classification?['entities'] as Map<String, dynamic>?;
            final dateStr = entities?['date'] as String? ?? '';
            final pnr = entities?['idNumber'] as String? ?? '';

            if (dateStr.isNotEmpty) {
              final parsedDate = _tryParseDate(dateStr);
              if (parsedDate != null) {
                final diffHours = parsedDate.difference(now).inHours;
                // Upcoming within 48 hours and not in the past
                if (diffHours >= 0 && diffHours <= 48) {
                  return ProactiveInsight(
                    id: 'ticket_alert_${m.id}',
                    type: InsightType.upcomingTicket,
                    title: 'Upcoming Travel / Ticket Alert',
                    message:
                        'Scheduled journey within $diffHours hours ($dateStr)${pnr.isNotEmpty ? ' • PNR: $pnr' : ''}. Check boarding details.',
                    timestamp: now,
                    metadata: {
                      'date': dateStr,
                      'pnr': pnr,
                      'hoursRemaining': diffHours,
                    },
                  );
                }
              }
            }
          }
        } catch (_) {}
      }
    }

    return null;
  }

  static bool _isSameDay(DateTime a, DateTime b) {
    return a.year == b.year && a.month == b.month && a.day == b.day;
  }

  static DateTime? _tryParseDate(String str) {
    try {
      return DateTime.tryParse(str);
    } catch (_) {
      return null;
    }
  }
}
